export function NewsletterSignup({
  heading = "{{heading}}",
  buttonLabel = "{{buttonLabel}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  privacy = {{privacy}},
}) {
  const wrapStyle = layout === "inline"
    ? { display: "flex", alignItems: "center", justifyContent: "space-between", gap: 20, flexWrap: "wrap" }
    : { display: "flex", flexDirection: "column", gap: 14 };
  return (
    <form style={{ fontFamily: "system-ui, sans-serif", color: "#241430", maxWidth: 420, ...wrapStyle }}>
      <div>
        <h3 style={{ margin: "0 0 4px", fontSize: 17, fontWeight: 700 }}>{heading}</h3>
        {privacy && <p style={{ margin: 0, fontSize: 12, color: "#241430aa" }}>No spam. Unsubscribe anytime.</p>}
      </div>
      <div style={{ display: "flex", flexDirection: layout === "stacked" ? "column" : "row", gap: 8 }}>
        <label htmlFor="newsletter-email" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)", whiteSpace: "nowrap" }}>Email address</label>
        <input id="newsletter-email" type="email" required placeholder="you@example.com" style={{ font: "14px system-ui, sans-serif", padding: "10px 12px", borderRadius: 8, border: "1.5px solid #24143033", minWidth: 200 }} />
        <button type="submit" style={{ border: "none", background: accent, color: "#FAF7F2", fontWeight: 600, fontSize: 14, padding: "10px 16px", borderRadius: 8, cursor: "pointer", whiteSpace: "nowrap" }}>{buttonLabel}</button>
      </div>
    </form>
  );
}
